                    {" · "}
                    {new Date(entry.created).toLocaleTimeString("de-DE", {
                      hour: "2-digit",
                      minute: "2-digit",
                    })} Uhr
                  </p>
                </Link>
                <div className="flex items-center gap-2 shrink-0">
